function [m] = ram_attitude(vrel)
%RAM_ATTITUDE  dgeom.ramAttitude(vrel): body to ECI with body +x along vrel and body +y = zref x x (zref +z, or +y when x is within
%   about 11 degrees of it).
%   vrel: real[1][3] (passed a plain number)
%   returns m: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 3);
    x = asils.models.drag.ounit(vrel);
    zref = [0; 0; 1];
    if (asils.pc.fabs(asils.pc.dot_(x, zref)) > 0.98)
        zref = [0; 1; 0];
    end
    y = asils.models.drag.ounit(asils.pc.cross_(zref, x));
    z = asils.pc.cross_(x, y);
    m = asils.models.drag.from_cols(x, y, z);
end
